from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.pdfgen import canvas
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Image, KeepTogether
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from PIL import Image as PILImage

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'Documentation';OUT.mkdir(exist_ok=True)
FONT=Path('/usr/share/fonts/truetype/dejavu')
# Authoring dependency; PDFs are already generated for recipients.
pdfmetrics.registerFont(TTFont('IRSans',str(FONT/'DejaVuSans.ttf')))
pdfmetrics.registerFont(TTFont('IRSans-Bold',str(FONT/'DejaVuSans-Bold.ttf')))
NAVY=colors.HexColor('#0a101d');GOLD=colors.HexColor('#edbb79');MUTED=colors.HexColor('#566276');PALE=colors.HexColor('#f3f5f8')
WIDTH,HEIGHT=612,792;CONTENT=516
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='IRTitle',fontName='IRSans-Bold',fontSize=25,leading=31,textColor=NAVY,spaceAfter=12))
styles.add(ParagraphStyle(name='IRH',fontName='IRSans-Bold',fontSize=15,leading=20,textColor=NAVY,spaceBefore=10,spaceAfter=7))
styles.add(ParagraphStyle(name='IRBody',fontName='IRSans',fontSize=10.6,leading=15.5,textColor=NAVY,spaceAfter=9))
styles.add(ParagraphStyle(name='IRSmall',fontName='IRSans',fontSize=8.7,leading=12,textColor=MUTED,spaceAfter=7))
styles.add(ParagraphStyle(name='IRCell',fontName='IRSans',fontSize=9.4,leading=13.5,textColor=NAVY))
styles.add(ParagraphStyle(name='IRCellWhite',fontName='IRSans-Bold',fontSize=9.3,leading=13,textColor=colors.white))

def p(text,style='IRBody'):return Paragraph(text,styles[style])
def title(text,sub=None):return [p(text,'IRTitle')]+([p(sub,'IRSmall')] if sub else [])
def h(text):return p(text,'IRH')
def note(text):
 t=Table([[p(text)]],colWidths=[CONTENT]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#fff3df')),('BOX',(0,0),(-1,-1),0.6,GOLD),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),5)]));return t

def table(headers,rows,widths=None):
 widths=widths or [145,371]
 data=[[p(escape(x),'IRCellWhite') for x in headers]]+[[p(escape(str(x)),'IRCell') for x in row] for row in rows]
 t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('ROWBACKGROUNDS',(0,1),(-1,-1),[PALE,colors.white]),('LINEBELOW',(0,0),(-1,0),1.2,GOLD)]))
 return t

def img(path,width):
 w,h=PILImage.open(path).size;return Image(str(path),width=width,height=width*h/w)

def build(filename,label,story):
 def page(c,doc):
  c.saveState();c.setFillColor(NAVY);c.rect(0,HEIGHT-75,WIDTH,75,fill=1,stroke=0)
  c.drawImage(str(ROOT/'Branding/IRChoir-Logo.png'),45,HEIGHT-65,width=174,height=58,mask='auto',preserveAspectRatio=True,anchor='c')
  c.setFillColor(GOLD);c.setFont('IRSans-Bold',9);c.drawRightString(WIDTH-48,HEIGHT-39,label.upper())
  c.setStrokeColor(GOLD);c.setLineWidth(0.7);c.line(48,38,WIDTH-48,38)
  c.setFillColor(MUTED);c.setFont('IRSans',8);c.drawString(48,24,'I.R.Choir  |  v0.3.0 prototype  |  23 October 2026')
  c.drawRightString(WIDTH-48,24,str(doc.page));c.restoreState()
 doc=SimpleDocTemplate(str(OUT/filename),pagesize=(WIDTH,HEIGHT),leftMargin=48,rightMargin=48,topMargin=96,bottomMargin=54,title='I.R.Choir - '+label,author='I.R.Choir')
 doc.build(story,onFirstPage=page,onLaterPages=page)

quick=[]
quick+=title('Quick start','Start here - read the build status before installing.')
quick+=[note('<b>The source ZIP is not an installer.</b> It contains no Mac DMG, AU or VST3 binary. A successful Mac build must create those files. If you have a generated DMG, use its included package installer.'),h('1. Get the correct installer'),p('If you already have a successful Mac build, open its DMG and run the I.R.Choir package installer. If you have this source bundle only, follow the Mac build instructions in the Release and Test Report or double-click Build-I.R.Choir.command on a Mac with the required tools.'),h('2. Install the native plugins'),p('Quit your DAW. Mount the DMG, read its welcome and audit, and run the .pkg. Restart the DAW and rescan plugins. The target is macOS 12 or later, on Apple Silicon or Intel; Mac validation is still pending for this release.'),table(['Format','Installed bundle'],[['AU','/Library/Audio/Plug-Ins/Components/IRChoir.component'],['VST3','/Library/Audio/Plug-Ins/VST3/IRChoir.vst3']],[80,436]),h('3. Make your first sound'),p('Feed a clean, single-voice vocal into the plugin. Choose <b>Intimate</b> or <b>Wide</b>. Begin in <b>Unison</b> mode. Adjust Choir Mix, Stereo Width and Room. Lower Output if the clip indicator lights.'),p('For a singer solo, turn Choir Mix to 100% so the dry input is not heard alongside the soloed layer. MIDI keys alone do not generate a voice.'),note('<b>Sound engine:</b> I.R.Choir layers and processes your input. It does not include distinct AI singers, choir recordings, a word builder or text-to-singing.')]
quick+=[PageBreak()]+title('Meet your choir','An actual native editor capture, not a rendered concept.')
quick+=[img(ROOT/'TestEvidence/IRChoir-Native-Interface.png',460),Spacer(1,10),table(['Area','Start with this'],[['Choir stage','Click a singer; drag left/right for pan or up/down for level. Shift-click to select several. Double-click to mute.'],['Section controls','Select a part or all singers. Use the group controls below the singer inspector.'],['Conductor','Move vertically for intensity and horizontally for space. Equivalent sliders are on the Humanize page.'],['Control page menu','Switch between performance, humanize, EQ/dynamics, delay and four-part controls.'],['Meters','Watch output peaks and clipping; use Mono audition to check stereo cancellation.']],[112,404])]
build('IRChoir-Quick-Start.pdf','Quick start',quick)

manual=[]
manual+=title('User guide','A practical guide to the current native vocal ensemble effect.')
manual+=[h('What I.R.Choir does'),p('I.R.Choir creates an ensemble from a vocal audio input using delayed, modulated and pitch-shifted layers. You can position and mix those layers, shape their synthetic tone colors, and add master effects.'),note('<b>Prototype boundary:</b> the result is not a trained choir conversion model. Bass, tenor, alto and soprano labels organize processed parts; they are not sampled human voice types.'),h('The signal path'),p('Vocal input → choir layers and part processing → dry/wet blend → low/high EQ → saturation → linked compression → delay → algorithmic room → output gain → optional mono audition.'),h('Choose a simple starting workflow'),table(['Goal','Starting point'],[['Subtle vocal thickening','Tight Doubles; low Room and moderate Choir Mix.'],['Wide backing layer','Wide Backing or Wide; adjust Stereo Width and monitor mono.'],['Atmospheric texture','Cloud or Dream Haze; listen carefully to consonants and pitch stability.'],['Relative harmony','Choose four relative parts and edit the four interval knobs.'],['MIDI harmony','Route input audio plus MIDI notes; use a clear monophonic guide.']]),h('Before important work'),p('Test on a copy of a DAW project. Listen at matched loudness against bypass. The automated tests establish software behavior, not musical realism or target-host reliability.')]
manual+=[PageBreak()]+title('The interactive stage')
manual+=[table(['Action','Result'],[['Click a singer','Select it for individual level, pan, mute, solo and synthetic color.'],['Shift-click','Add or remove singers from the selection.'],['Drag a selected singer','Move the selection in stereo and adjust its level. Vertical movement is visually limited to keep rows legible.'],['Click empty stage space','Clear a group selection before selecting one singer.'],['Double-click','Toggle that singer mute.'],['Bass / Tenor / Alto / Soprano','Select every active layer in that part.'],['All singers','Select every active layer.'],['Group pan','Apply a relative pan offset; the control returns to zero after dragging.'],['Group level','Set all selected layers to the displayed level.'],['Group mute / solo','Toggle the selection together. Solo affects wet layers only.']]),h('Formations'),p('<b>Semicircle</b> curves the stage; <b>Tight cluster</b> narrows placement; <b>Wide rows</b> spreads singers across the stereo field. Applying a formation resets singer pan and level. Reapply after changing ensemble size to space the current singers again.'),h('Animation'),p('Full and Subtle modes animate the actual layer meters. Distinct faces, hairstyles and choir robes identify the visual layers; these are not separate voice models. Reduced motion removes mouth and singer glow animation while retaining slow meter refresh. The Humanize sliders provide a conventional alternative to dragging the conductor pad.')]
manual+=[PageBreak()]+title('Performance and humanize')
manual+=[table(['Control','What changes'],[['Ensemble Size','2 to 32 active layers. Higher counts increase processing cost.'],['Choir Mix','Blend the original vocal and processed ensemble. At 100%, only wet layers remain.'],['Stereo Width','Scale individual pan positions; there is no pan effect in a mono output.'],['Human Motion','Slow delay modulation across singers.'],['Timing Looseness','Vary the small delay offsets between layers.'],['Pitch Drift','Slow pitch variation, expressed in cents.'],['Vibrato','Additional pitch movement in cents.'],['Intensity','Layer gain and modulation intensity; the conductor vertical axis.'],['Space','Controls ambience strength with Room; the conductor horizontal axis.'],['Synthetic Character','Blend each layer with its warm/airy/dark/bright filter color.'],['Output','Final gain after all effects. Clip indication is not limiting.']]),h('Getting a natural result'),p('Use small timing and pitch amounts before increasing layer count. Keep some dry signal for intelligibility. Excessive width or movement can weaken consonants or produce phase cancellation. A 12-layer setting is not automatically better than a 4-layer setting.'),h('Synthetic voice colors'),p('Warm, Airy, Dark and Bright are tonal filters, not voice identities. Distinct recorded or AI singers require separately licensed recordings or a trained model that is not included.')]
manual+=[PageBreak()]+title('Effects and metering')
manual+=[table(['Effect','Use and limits'],[['Low / High EQ','Tone shelves around the low and high regions; not a full surgical equalizer.'],['Saturation','Adds nonlinear color. Increase carefully and compare at matched loudness.'],['Compression','Linked stereo envelope control to reduce high-level peaks; no automatic makeup gain.'],['Delay Mix','Add delayed repeats.'],['Delay Time','50-1000 ms. Changes are smoothed and can create tape-like pitch movement.'],['Feedback','Controls repeat decay; limited to 0.8 for stability.'],['Room type','Six algorithmic spaces, including Chamber, Plate-style and Tunnel-style; no measured impulse responses.'],['Room','Master ambience blend; also affected by the conductor Space control.']]),h('Read the meters'),p('<b>L/R</b> show peak output in dBFS. <b>CLIP</b> stays lit after an overload until cleared. <b>Correlation</b> approaches +1 for similar left/right signals and can go negative when they oppose each other. <b>Mono RMS</b> measures the level after summing, before Mono audition is applied.'),p('Use Mono audition while adjusting width. If the choir becomes much quieter or thin, reduce width and motion and compare again. The vocal guide frequency is an approximate pitch estimate, not a tuning meter.'),h('Smoothing'),p('The engine ramps major mix, level, gate, conductor and FX changes. This reduces abrupt control jumps but does not establish artifact-free sound under every automation pattern.')]
manual+=[PageBreak()]+title('Shape the reverb','Open Reverb space from the control-page menu.')
manual+=[p('Choose Studio, Hall, Cathedral, Chamber, Plate-style or Tunnel-style. All are algorithmic settings; no EastWest recordings or convolution impulse responses are included.'),table(['Control','Action'],[['Reverb on','Enable the wet return; switching off restores the dry signal with a short fade.'],['Mono send','Sum the input sent to the reverb while leaving the dry stereo image intact.'],['Low cut / High cut','Toggle the send filters; frequency knobs set their cutoff.'],['Freeze','Hold the reverb tail. Turn off to release it; lower Room before experimenting.'],['Wet only','Hear the reverb return without the dry vocal. Reverb off restores dry audio.'],['Pre-delay','0-200 ms before the reverb; Tunnel-style adds 9 ms of spacing.'],['Decay shape','Relative room decay adjustment, not calibrated seconds.'],['Reverb width','Set the stereo width of the wet return.'],['Damping','Soften high frequencies as the reverb decays.'],['Room / conductor Space','Control the wet return amount from Performance and the conductor pad.']]),p('Start with Hall, a low Room level, 12-30 ms pre-delay and some low cut. Use wet-only listening to tune the space, then return to the full mix. These recommendations are starting points for listening, not measured acoustic models.')]
manual+=[PageBreak()]+title('Presets, favourites and history')
manual+=[table(['Factory preset','Intended character'],[['Intimate','4 restrained layers with little ambience.'],['Wide','12 broad backing layers.'],['Cloud','24 layers with more motion and space.'],['Massive','32 dense layers.'],['Tight Doubles','2 layers, subtle movement, no room.'],['Wide Backing','12 layers, a little compression and high tone.'],['Dream Haze','24 layers with delay and darker high tone.'],['Cathedral','16 layers with the largest algorithmic room.'],['Crowd Wash','32 layers with stronger movement and color.']]),h('Save and find your own sounds'),p('Type a name and click Save. A new .irchoir.xml file is created in your user application-data location under IRChoir/Presets. Existing files are not silently overwritten. Star the current preset to mark it as a favourite; Favourites filters the browser.'),h('A/B and undo'),p('A/B saves the current side before loading the other. Copy sends the current sound to the other side. Both snapshots survive closing the editor while the plugin instance exists, but only the current sound is saved with a DAW project.'),p('Undo and Redo cover parameter edits. Whole preset-file loading and A/B replacement are separate state operations. Preset names do not show every unsaved change. Loading a factory preset resets sonic parameters and singer edits; animation preference is retained.')]
manual+=[PageBreak()]+title('Four parts and MIDI')
manual+=[h('Relative parts'),p('Each active layer is assigned to one of four repeating parts. Set their levels independently and choose intervals from -12 to +12 semitones. The default offsets are -12, -5, 0 and +7 relative to your incoming vocal. This creates processed harmony layers; it does not change the source into four authentic human voice types.'),h('MIDI targets'),p('Choose MIDI note targets, route MIDI into the plugin using your host, and send a stable monophonic vocal to the audio input. The engine estimates the input pitch and shifts parts toward held MIDI notes. Sustain and channel-aware note release are supported.'),table(['Behavior','Current implementation'],[['Which notes?','The lowest four unique held notes. When fewer notes are held, the highest available note repeats.'],['Shift range','At most one octave up or down relative to the detected input.'],['No held notes','The wet layers are gated off. Dry signal may remain, depending on Choir Mix.'],['No stable pitch','The MIDI wet layers are gated off; unvoiced sounds can be affected.'],['Guide range','Approximate monophonic detection, about 65-1000 Hz.'],['Formants','No formant preservation; large shifts can sound synthetic.']]),h('Example'),p('With a clear A3 guide (about 220 Hz), try held notes A2, E3, A3 and E4. Begin with low movement and no master effects. Judge note transitions and consonant clarity before adding ambience.'),h('AU routing'),p('The AU is a MIDI-controlled audio effect. In Logic and other hosts, the route may differ from a normal audio insert. MIDI alone does not create sound; a vocal audio source is still required.')]
manual+=[PageBreak()]+title('Troubleshooting and care')
manual+=[table(['Symptom','Check'],[['No plugin in the DAW','Confirm a real Mac build exists, the correct format was installed, and a rescan completed. Read host scan errors.'],['No wet sound','Check audio input, mutes/solos, Choir Mix and MIDI held notes if MIDI mode is selected.'],['Metallic or smeared sound','Reduce shifts, drift, vibrato and motion. Try fewer layers and a cleaner vocal. Granular artifacts remain a known limitation.'],['Clipping','Reduce Output, drive, EQ boost, delay feedback and layer level.'],['Weak mono sound','Reduce width/motion, audition the mono sum and watch correlation.'],['Preset cannot save','Check application-data folder permissions. The UI reports failure rather than claiming success.'],['Too much CPU','Use fewer layers. Try Subtle or Reduced motion. Measure in the actual DAW at your buffer size.'],['macOS blocks the file','Verify the build origin and signing status. Do not disable Gatekeeper globally.']]),h('Remove the plugin'),p('Quit the DAW and remove IRChoir.component from /Library/Audio/Plug-Ins/Components and IRChoir.vst3 from /Library/Audio/Plug-Ins/VST3. Rescan. Your separately stored presets remain.'),h('Report a reproducible problem'),p('Record the plugin version, Mac model/chip, macOS, DAW/version, AU or VST3, sample rate, buffer size, preset and exact steps. Include scan/crash logs. Supply a short audio example only if you own or have permission to share it.'),note('<b>Before public release:</b> Mac validation, installer checks, target-DAW testing and real-vocal listening are still required. Consult the Release and Test Report for the exact executed coverage.')]
build('IRChoir-User-Guide.pdf','User guide',manual)

release=[]
release+=title('Release & test report','Build record, installation pipeline and remaining release gates.')
release+=[note('<b>Release status: prototype.</b> Linux VST3 and native automated checks passed. No Mac AU/VST3 binary, DMG, Apple signature or notarization result has been produced in this session.'),h('Executed coverage'),table(['Check','Recorded result'],[['Linux Release build','PASS - pinned JUCE 8.0.6, x86_64 VST3 and native editor/processor.'],['DSP tests','PASS - three sample rates, silence reset, octave-shift spectrum, correlation and mono cancellation.'],['Processor/editor smoke','PASS - rates 44.1/48/96 kHz, block sizes 1/64/512, three modes, FX extremes, finite output, mono, state and MIDI release/sustain/panic. Reverb: bypass, wet-only pre-delay, 192 room/toggle combinations and recall.'],['UI and persistence','PASS - native creation/resize, formations, groups, conductor and singer dragging, mute, preset save/load, favourites, A/B and undo/redo.'],['pluginval 1.0.4','PASS - Linux VST3 strictness 5, seed 12345, GUI checks skipped. Native editor has separate offscreen tests.'],['Sanitizers','PASS for standalone DSP helpers with ASan/UBSan. LeakSanitizer was disabled due environment restrictions.'],['Packaging','Static shell/XML/YAML checks only. No Apple packaging command was executed.']],[132,384]),p('Raw evidence, source and the actual editor screenshot are included in TestEvidence. These checks do not replace listening tests or prove compatibility with any named Mac DAW.','IRSmall')]
release+=[PageBreak()]+title('Performance & sound quality')
release+=[h('Observed render cost'),p('Release build, 48 kHz, 256-sample blocks, two seconds of a 220 Hz stereo guide, this Linux environment. Budget is wall-clock render time divided by audio duration, not an OS CPU measurement.'),table(['Layers','Before','After','Observed reduction'],[['2','16.93%','1.30%','About 92%'],['12','16.65%','3.71%','About 78%'],['32','17.15%','8.56%','About 50%']],[65,110,110,231]),h('What changed'),p('Inactive voice slots stop processing after fade-out. Pitch targets are computed every 16 samples and interpolated. Major mix/FX/conductor changes, MIDI gates and delay time are smoothed. Delay reads use fractional interpolation.'),h('What these results do not establish'),p('Mac performance, real-time dropout limits, leak freedom, realistic human singers, formant preservation, correct pronunciation or parity with a commercial AI choir plugin have not been established.'),h('Listening plan'),p('Use a short dry vocal with sustained notes, pitch changes, words and unvoiced consonants. Compare bypass, Tight Doubles, Intimate and Wide at matched loudness. First judge pitch stability and word clarity with effects off; then add width and ambience. Check headphones, speakers and mono.'),p('Only after the simple unison sound is convincing should the project add a trained choir model. That requires appropriate rights to voices and recordings, a compatible inference engine and independent performance tests.')]
release+=[PageBreak()]+title('Build the Mac installer')
release+=[h('Option A: a dedicated GitHub repository'),p('1. Create or choose a repository for I.R.Choir.<br/>2. Upload the <b>contents</b> of the project folder at its root, including the hidden .github folder.<br/>3. Push to main/master, or run <b>Build and audit Mac DMG</b> from Actions.<br/>4. The Mac runner builds arm64 and x86_64 AU/VST3, runs CTest, packages the DMG, and invokes pluginval and auval.<br/>5. Download the installer artifact only after a successful workflow. Test evidence is offered separately.'),h('Option B: build on your Mac'),p('Install CMake and Xcode command line tools, then double-click <b>Build-I.R.Choir.command</b> or run <b>bash Scripts/build-mac.sh</b> from the project root. Read errors if a tool, dependency or test is missing; do not treat a failed run as an installer.'),h('Installer contents'),p('The resulting DMG is designed to contain a branded Apple Installer .pkg, the three PDF guides, audit text, licenses and corresponding source archives. The package installs precompiled AU and VST3 bundles. It does not compile anything on the recipient Mac.'),h('Signing is optional and separate'),p('The default output is unsigned/unnotarized. For signed distribution, existing Developer ID Application and Installer certificates must be in the Mac keychain. Set IRCHOIR_APP_IDENTITY and IRCHOIR_INSTALLER_IDENTITY. An existing IRCHOIR_NOTARY_PROFILE enables submission, acceptance checking and DMG stapling.'),note('No Apple credentials are included or requested inside the project files. VST2 and AAX are not part of this build. The branded Apple Installer flow and DMG packaging still require actual Mac execution.')]
release+=[PageBreak()]+title('Release gates & audit findings')
release+=[table(['Gate','Current status'],[['Native Mac build','Pending: universal arm64/x86_64 build and architecture checks.'],['Mac plugin validation','Pending: auval plus VST3 validation, host scan and routing.'],['Installer verification','Pending: mount DMG, inspect payload, install, rescan, uninstall and preserve presets on a fresh Mac.'],['DAW reliability','Pending: real sessions, automation, reopen/recall, long playback and dropouts.'],['Musical evaluation','Pending: real-vocal comparison, consonant clarity, pitch transitions, mono and loudness matching.'],['AI singer identities','Not implemented. Synthetic filters are not a replacement.'],['Warning cleanup','Some aggressive compiler conversion warnings remain; explicit cleanup is appropriate before production.'],['Distribution rights','Review JUCE and any future model/data licenses before distributing.']]),h('Material fixes made'),p('Corrected invalid JUCE GUI color identifiers; removed dotted native bundle filenames that broke VST3 loading; prevented formation recall from resetting singer positions; corrected mono panning and output-gain order; fixed stage/meter overlap and stale screenshot output; isolated preset tests from real user files.'),h('Source and licensing'),p('Original source is offered under AGPL-3.0-or-later; the full text is included. JUCE 8.0.6 has its own AGPL/commercial licensing. The default DMG script includes corresponding source and license copies. No commercial choir samples or AI weights are included.'),p('This is an engineering build report, not a certification of sound quality, licensing compliance or public-release readiness. The executable test logs and later Mac runner results take precedence over assumptions.','IRSmall')]
build('IRChoir-Release-and-Test-Report.pdf','Release and test report',release)
print('Created:',*[p.name for p in OUT.glob('*.pdf')])
